import{_ as t,c as r,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"はじめに","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/introduction.md","filePath":"ja/guide/introduction.md","lastUpdated":1793163976000}'),n={name:"ja/guide/introduction.md"};function l(e,a,s,g,h,d){return i(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h1><h2 id="nuezip-について" tabindex="-1">NueZip について <a class="header-anchor" href="#nuezip-について" aria-label="Permalink to &quot;NueZip について&quot;">​</a></h2><p>NueZip は、速度、信頼性、使いやすさを追求して設計された、macOS 向けのプロフェッショナルなアーカイブマネージャーです。ファイルの圧縮、アーカイブの展開、フォーマットの変換、パスワード保護されたアーカイブの管理など、NueZip はすべてをネイティブな macOS 体験で処理します。</p><p>Swift 6 と SwiftUI で構築された NueZip は、Apple Silicon と macOS の技術を最大限に活用し、高速で軽量かつ安全なアーカイブ管理ツールを提供します。</p><h2 id="主な機能" tabindex="-1">主な機能 <a class="header-anchor" href="#主な機能" aria-label="Permalink to &quot;主な機能&quot;">​</a></h2><h3 id="📦-マルチフォーマット対応" tabindex="-1">📦 <strong>マルチフォーマット対応</strong> <a class="header-anchor" href="#📦-マルチフォーマット対応" aria-label="Permalink to &quot;📦 **マルチフォーマット対応**&quot;">​</a></h3><p>NueZip はすべての主要なアーカイブフォーマットをサポートします：</p><ul><li><strong>RAR</strong> — マルチボリューム対応の読み取り専用</li><li><strong>ZIP</strong> — AES 暗号化を備えた汎用圧縮</li><li><strong>7-Zip</strong> — LZMA2 による高圧縮率</li><li><strong>TAR</strong> — オプションの GZIP/BZIP2 を伴うアーカイブのバンドル</li><li><strong>GZIP / BZIP2</strong> — 単独の圧縮フォーマット</li></ul><h3 id="⚡-高速な展開" tabindex="-1">⚡ <strong>高速な展開</strong> <a class="header-anchor" href="#⚡-高速な展開" aria-label="Permalink to &quot;⚡ **高速な展開**&quot;">​</a></h3><p>デュアルエンジンアーキテクチャが各フォーマットに最適なバックエンドを選択し、可能な限り高速な展開速度を実現します。</p><h3 id="🔐-パスワード保護と暗号化" tabindex="-1">🔐 <strong>パスワード保護と暗号化</strong> <a class="header-anchor" href="#🔐-パスワード保護と暗号化" aria-label="Permalink to &quot;🔐 **パスワード保護と暗号化**&quot;">​</a></h3><p>業界標準の暗号化を用いて、パスワードで保護されたアーカイブを作成できます。内蔵のパスワードマネージャーが資格情報をローカルのキーチェーンに安全に保存します。</p><h3 id="📋-バッチ操作" tabindex="-1">📋 <strong>バッチ操作</strong> <a class="header-anchor" href="#📋-バッチ操作" aria-label="Permalink to &quot;📋 **バッチ操作**&quot;">​</a></h3><p>複数のファイルを一度に処理できます：</p><ul><li><strong>バッチ圧縮</strong> — 複数の項目を個別のアーカイブに圧縮する</li><li><strong>バッチ展開</strong> — 複数のアーカイブを同時に展開する</li><li><strong>バッチ変換</strong> — フォーマット間でアーカイブを一括変換する</li><li><strong>バッチ暗号化</strong> — 複数のアーカイブにパスワード保護を適用する</li></ul><h3 id="🛠️-高度なツール" tabindex="-1">🛠️ <strong>高度なツール</strong> <a class="header-anchor" href="#🛠️-高度なツール" aria-label="Permalink to &quot;🛠️ **高度なツール**&quot;">​</a></h3><ul><li><strong>アーカイブ修復</strong> — 破損した RAR および ZIP アーカイブを修復する</li><li><strong>フォーマット変換</strong> — 対応する任意のフォーマット間で変換する</li><li><strong>パフォーマンスベンチマーク</strong> — 圧縮速度と評価をテストする</li><li><strong>アーカイブ検索</strong> — アーカイブ内のファイルを名前で検索する</li><li><strong>ファイル情報ビューア</strong> — アーカイブ項目の詳細なメタデータを表示する</li><li><strong>ボリューム/分割対応</strong> — マルチボリュームアーカイブを作成する</li></ul><h3 id="🖥️-ネイティブな-macos-体験" tabindex="-1">🖥️ <strong>ネイティブな macOS 体験</strong> <a class="header-anchor" href="#🖥️-ネイティブな-macos-体験" aria-label="Permalink to &quot;🖥️ **ネイティブな macOS 体験**&quot;">​</a></h3><ul><li><strong>Swift 6 + SwiftUI</strong> — モダンで応答性の高いインターフェイス</li><li><strong>Apple Silicon ネイティブ</strong> — M シリーズチップに最適化</li><li><strong>Finder 統合</strong> — 右クリックのコンテキストメニュー拡張</li><li><strong>ドラッグ＆ドロップ</strong> — メニューバーのドロップパネルからのクイックアクセス</li><li><strong>最小限のリソース使用</strong> — 軽量なバックグラウンド動作</li></ul><h2 id="システム要件" tabindex="-1">システム要件 <a class="header-anchor" href="#システム要件" aria-label="Permalink to &quot;システム要件&quot;">​</a></h2><ul><li><strong>オペレーティングシステム</strong>: macOS 14 Sonoma 以降</li><li><strong>CPU</strong>: Apple Silicon（M シリーズ）または Intel（64-bit）</li><li><strong>メモリ</strong>: 最小 4GB RAM、推奨 8GB</li><li><strong>ストレージ</strong>: インストールに約 50 MB</li></ul><h2 id="対応言語" tabindex="-1">対応言語 <a class="header-anchor" href="#対応言語" aria-label="Permalink to &quot;対応言語&quot;">​</a></h2><p>NueZip は英語、中国語（簡体字）、中国語（繁体字）、日本語、韓国語、および他の多くの言語をサポートしています。</p><h2 id="はじめに-1" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに-1" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>NueZip を初めてお使いの場合は、<a href="/ja/guide/installation.html">インストールガイド</a> から始めて、アプリケーションを Mac で動作させてください。</p>',25)])])}const p=t(n,[["render",l]]);export{c as __pageData,p as default};
